int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char S[200005];
    scanf("%s", S);

    const int INF = 1e9;

    int *dp = (int *)malloc((N + 1) * sizeof(int));
    int *next = (int *)malloc((N + 1) * sizeof(int));
    int *deq = (int *)malloc((N + 2) * sizeof(int));

    for (int i = 0; i <= N; i++) {
        dp[i] = INF;
        next[i] = -1;
    }

    dp[N] = 0;

    int head = 0, tail = 0;
    deq[tail++] = N;

    for (int i = N - 1; i >= 0; i--) {
        while (head < tail && deq[head] > i + M) head++;

        if (S[i] == '1') {
            dp[i] = INF;
        } else if (head < tail) {
            int j = deq[head];
            dp[i] = dp[j] + 1;
            next[i] = j;
        }

        if (dp[i] < INF) {
            while (head < tail) {
                int k = deq[tail - 1];
                if (dp[k] > dp[i] || (dp[k] == dp[i] && k > i)) tail--;
                else break;
            }
            deq[tail++] = i;
        }
    }

    if (dp[0] >= INF) {
        printf("-1\n");
        free(dp);
        free(next);
        free(deq);
        return 0;
    }

    int *ans = (int *)malloc((dp[0] + 5) * sizeof(int));
    int cnt = 0;
    int cur = 0;
    while (cur != N) {
        int nxt = next[cur];
        ans[cnt++] = nxt - cur;
        cur = nxt;
    }

    for (int i = 0; i < cnt; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(dp);
    free(next);
    free(deq);
    free(ans);
    return 0;
}

