    int N, M;
    string S;
    cin >> N >> M >> S;

    const int INF = 1e9;
    vector<int> dist(N + 1, INF);
    dist[N] = 0;

    // We can use a deque / sliding window min to compute distances from right to left
    // For each position i, we can jump to i+1 .. i+M (if not game over)
    // So dist[i] = 1 + min(dist[i+1..i+M]) if S[i] != '1'

    // We'll maintain a multiset for the window of size M
    multiset<int> window;
    window.insert(dist[N]); // dist[N] = 0

    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == '1') {
            dist[i] = INF;
        } else {
            if (!window.empty()) {
                dist[i] = 1 + *window.begin();
            }
        }
        // Slide window: remove i+M+1, add i
        if (i + M <= N) {
            window.erase(window.find(dist[i + M]));
        }
        window.insert(dist[i]);
    }

    if (dist[0] >= INF) {
        cout << -1 << "\n";
        return 0;
    }

    // Reconstruct lexicographically smallest
    vector<int> ans;
    int pos = 0;
    while (pos < N) {
        // Try from smallest move to largest
        for (int step = 1; step <= M; ++step) {
            int nxt = pos + step;
            if (nxt > N) break;
            if (S[nxt] == '1') continue;
            if (dist[nxt] == dist[pos] - 1) {
                ans.push_back(step);
                pos = nxt;
                break;
            }
        }
    }

    for (size_t i = 0; i < ans.size(); ++i) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
