int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    string S;
    cin >> N >> M >> S;

    const int INF = 1e9;

    // dp[i] = minimum number of moves needed to reach N from square i
    vector<int> dp(N + 1, INF);
    dp[N] = 0;

    // Segment tree for range minimum query on dp
    int SZ = 1;
    while (SZ < N + 1) SZ <<= 1;
    vector<pair<int,int>> seg(2 * SZ, {INF, INF}); // {dp value, index}

    auto better = [&](pair<int,int> a, pair<int,int> b) {
        if (a.first != b.first) return (a.first < b.first ? a : b);
        return (a.second < b.second ? a : b);
    };

    auto update = [&](int pos, pair<int,int> val) {
        pos += SZ;
        seg[pos] = val;
        while (pos >>= 1) {
            seg[pos] = better(seg[pos << 1], seg[pos << 1 | 1]);
        }
    };

    auto query = [&](int l, int r) {
        pair<int,int> L = {INF, INF}, R = {INF, INF};
        for (l += SZ, r += SZ; l < r; l >>= 1, r >>= 1) {
            if (l & 1) L = better(L, seg[l++]);
            if (r & 1) R = better(seg[--r], R);
        }
        return better(L, R);
    };

    update(N, {0, N});

    for (int i = N - 1; i >= 0; --i) {
        if (S[i] == '1') continue;
        int l = i + 1;
        int r = min(N, i + M) + 1;
        auto best = query(l, r);
        if (best.first != INF) {
            dp[i] = best.first + 1;
            update(i, {dp[i], i});
        }
    }

    if (dp[0] == INF) {
        cout << -1 << '\n';
        return 0;
    }

    vector<int> ans;
    int cur = 0;
    while (cur < N) {
        // To get lexicographically smallest sequence of moves among minimum-turn solutions,
        // choose the smallest possible move length.
        for (int d = 1; d <= M && cur + d <= N; ++d) {
            int nxt = cur + d;
            if (S[nxt] == '1') continue;
            if (dp[nxt] == dp[cur] - 1) {
                ans.push_back(d);
                cur = nxt;
                break;
            }
        }
    }

    for (int i = 0; i < (int)ans.size(); ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}

