    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        String S = sc.next();
        sc.close();

        int[] dp = new int[N + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[N] = 0;

        // Sliding window minimum for efficient DP
        Deque<Integer> deque = new ArrayDeque<>();
        deque.addLast(N);

        for (int i = N - 1; i >= 0; i--) {
            if (S.charAt(i) == '1') continue;
            // Remove out-of-range indices
            while (!deque.isEmpty() && deque.peekFirst() > i + M) {
                deque.pollFirst();
            }
            if (!deque.isEmpty()) {
                dp[i] = dp[deque.peekFirst()] + 1;
            }
            // Maintain deque in increasing order of dp value
            while (!deque.isEmpty() && dp[deque.peekLast()] >= dp[i]) {
                deque.pollLast();
            }
            deque.addLast(i);
        }

        if (dp[0] == Integer.MAX_VALUE) {
            System.out.println(-1);
            return;
        }

        // Reconstruct the path
        List<Integer> moves = new ArrayList<>();
        int pos = 0;
        while (pos < N) {
            // Find smallest step that leads to a valid next position
            for (int step = 1; step <= M; step++) {
                int next = pos + step;
                if (next <= N && S.charAt(next) != '1' && dp[next] == dp[pos] - 1) {
                    moves.add(step);
                    pos = next;
                    break;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < moves.size(); i++) {
            if (i > 0) sb.append(" ");
            sb.append(moves.get(i));
        }
        System.out.println(sb);
    }
