public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        String S = sc.next();

        // dist[i] = min turns from square i to square N
        int[] dist = new int[N + 1];
        Arrays.fill(dist, -1);
        dist[N] = 0;

        Queue<Integer> queue = new LinkedList<>();
        queue.add(N);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            // squares that can reach cur in one step: cur-1, cur-2, ..., cur-M
            for (int x = 1; x <= M; x++) {
                int prev = cur - x;
                if (prev < 0) break;
                if (dist[prev] != -1) continue;
                // check if prev is a game over square
                if (prev > 0 && S.charAt(prev - 1) == '1') continue;
                // square 0 is always valid (start)
                dist[prev] = dist[cur] + 1;
                queue.add(prev);
            }
        }

        if (dist[0] == -1) {
            System.out.println(-1);
            return;
        }

        // Reconstruct lexicographically smallest path
        StringBuilder sb = new StringBuilder();
        int cur = 0;
        while (cur != N) {
            for (int x = 1; x <= M; x++) {
                int next = cur + x;
                if (next > N) break;
                if (dist[next] == dist[cur] - 1) {
                    if (sb.length() > 0) sb.append(' ');
                    sb.append(x);
                    cur = next;
                    break;
                }
            }
        }

        System.out.println(sb.toString());
    }
}

