import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        String S = fs.next();

        // dp[i] = minimum number of moves needed to reach N from i
        // if impossible, INF
        int INF = 1 << 29;
        int[] dp = new int[N + 1];
        Arrays.fill(dp, INF);
        dp[N] = 0;

        // Segment tree for range minimum of dp
        SegTree seg = new SegTree(N + 1);
        seg.build(dp);

        for (int i = N - 1; i >= 0; i--) {
            if (S.charAt(i) == '1') {
                dp[i] = INF;
                seg.update(i, INF);
                continue;
            }
            int l = i + 1;
            int r = Math.min(N, i + M);
            int mn = seg.query(l, r + 1);
            if (mn < INF) dp[i] = mn + 1;
            seg.update(i, dp[i]);
        }

        if (dp[0] >= INF) {
            System.out.println(-1);
            return;
        }

        // Reconstruct lexicographically smallest sequence among minimum-turn solutions.
        // For moves sequence a1, a2, ..., ak, lexicographically smallest means smallest a1,
        // then smallest a2, etc.
        List<Integer> ans = new ArrayList<>();
        int pos = 0;
        while (pos < N) {
            for (int step = 1; step <= M && pos + step <= N; step++) {
                int np = pos + step;
                if (np < N && S.charAt(np) == '1') continue;
                if (dp[np] == dp[pos] - 1) {
                    ans.add(step);
                    pos = np;
                    break;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans.get(i));
        }
        System.out.println(sb.toString());
    }

    static class SegTree {
        int n;
        int[] tree;
        int INF = 1 << 29;

        SegTree(int sz) {
            n = 1;
            while (n < sz) n <<= 1;
            tree = new int[n << 1];
            Arrays.fill(tree, INF);
        }

        void build(int[] a) {
            for (int i = 0; i < a.length; i++) tree[n + i] = a[i];
            for (int i = n - 1; i >= 1; i--) tree[i] = Math.min(tree[i << 1], tree[i << 1 | 1]);
        }

        void update(int idx, int val) {
            int p = idx + n;
            tree[p] = val;
            while ((p >>= 1) > 0) tree[p] = Math.min(tree[p << 1], tree[p << 1 | 1]);
        }

        int query(int l, int r) {
            int res = INF;
            l += n;
            r += n;
            while (l < r) {
                if ((l & 1) == 1) res = Math.min(res, tree[l++]);
                if ((r & 1) == 1) res = Math.min(res, tree[--r]);
                l >>= 1;
                r >>= 1;
            }
            return res;
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
